SELECT CASE WHEN store_sales.units >= 32 THEN 'high' WHEN store_sales.units >= 18 THEN 'mid' ELSE 'low' END units_bucket, store_sales.store_id, AVG(inventory.quantity) avg_quantity FROM inventory JOIN store_sales ON inventory.store_id = store_sales.store_id AND inventory.product_id = store_sales.product_id GROUP BY CASE WHEN store_sales.units >= 32 THEN 'high' WHEN store_sales.units >= 18 THEN 'mid' ELSE 'low' END, store_sales.store_id;
